# Hand-written R5900 versions of the gfx_tests.c kernels (bench variants asm
# and asm-vu0), generated by asm/gen/app_files.py from asm/gen/gfx.py (the
# loops ordered by asm/gen/sched.py). n32 ABI. The kernels use the data of
# gfx_tests.c (KERNEL_DATA) and end with app_hash of their output as the C
# kernels do; about half the time of most of them is that hash.
#
# The 2D kernels use the GPRs and MMI in both variants. Of the 3D kernels,
# asm-vu0 (ASM_VU0) has VU0 macro-mode versions and asm FPU ones.
# Optimized: yes, all. Chosen by measuring variants on the PS2 (asm/harness/
# app.c), Mpix/s, Mvert/s, Mtri/s or Mobj/s, feature clang in parentheses:
#   Alpha Blend: MMI pmulth/pmaddh per 2 pixels, PREF 2 ahead: 23.2
#     (2 blocks per iteration 20.9, no PREF 17.3; feature 9.9)
#   CLUT8: palette addresses by MMI, PREF of frame 4 ahead: 28.2 (by srl,
#     andi, addu: 27.4; no PREF 26.5; feature 25.3)
#   Color Key, Alpha Test: MMI select, 8 blocks per iteration, no PREF:
#     20.2, 20.2 (PREF 2 ahead with the output: 20.0, 20.1; 4 blocks: 19.4,
#     19.3; feature 19.8, 19.1)
#   To CT16: ppac5, ppach, 32 pixels per iteration, PREF 4 ahead: 37.7
#     (8 pixels, no PREF: 36.1; feature 32.7)
#   Scale NN: unrolled rows, copies of repeated rows: 29.6 (feature 28.1)
#   GEOM, VU0 | FPU (feature-vu0 | feature):
#     Transform        6.19 | 4.90  (5.81 | 4.97: feature knows the zeros of
#                                    the matrix, the hand-written code does not)
#     Lighting        11.64 | 6.63  (9.29 | 5.63: the FPU version 2 vertices
#                                    per iteration; 1: 5.53)
#     Lighting v4sf   11.62 | 5.48  (8.88 | 5.61)
#     Field Scale      5.03 | 4.45  (4.71 | 4.24)   memory-bound, as the
#     Field Offset     5.03 | 4.45  (4.89 | 4.24)   MxV, Project and Face
#     Project          6.44 | 6.20  (6.27 | 5.99)   Normals
#     Weighted Sum    13.46 | 11.08 (12.81 | 9.30)
#     MxV 4x4          7.21 | 5.40  (7.06 | 5.20)
#     MxV 3x4          6.31 | 5.61  (6.43 | 5.27)
#     Backface Cull   12.20 (MMI)   (8.76 | 8.71)
#     Face Normals     6.70 | 5.96  (6.71 | 5.55)
#     Frustum Cull    12.35 | 5.57  (8.23 | 4.93)
#   PREF leads: 1-4 lines ahead differ by 1-3 %, none is worse than 6 %.

	.set	noreorder
	.set	noat

# gfx_mem: the offsets of its buffers
#define SPRITE		0x0000
#define FRAME		0x4400
#define INDEXED		0x8800
#define PALETTE		0x9c00
#define FRAME16		0xa000
#define SCALED		0xc400
# geom_mem
#define VERTS		0x0000
#define NORMALS		0x2400
#define SCALED_V	0x4800
#define FACE_NORMALS	0x6c00
#define SCREEN		0x9400
#define XFORMED		0xb800
#define COLORS		0xdc00
#define FACE_NORMALS_V	0xec00
#define VISIBLE		0x10c00

# reg = symbol + offset (any 32-bit offset), using $1
#define ADDR(reg, sym, off) \
	lui	$1, %hi(sym); addiu reg, $1, %lo(sym); \
	lui	$1, ((off) >> 16); ori $1, $1, ((off) & 0xffff); addu reg, reg, $1

	.text

# alpha_blend: frame = sprite over frame by its alpha
# MMI per 4 pixels: bytes to halfwords, alpha broadcast with pcpyh,
# pmulth s * a + pmaddh d * (256 - a) (the alpha halfwords 0 and 256:
# the result keeps d's alpha), pmfhl.lh, psrlh 8, ppacb. 1 blocks of
# 4 pixels per iteration, PREF 2 lines ahead.
	.p2align 3
	.globl	alpha_blend
	.ent	alpha_blend
alpha_blend:
	ADDR($8, gfx_mem, SPRITE)
	addiu	$9, $8, 16384
	daddiu	$10, $0, -1
	dsrl	$10, $10, 16
	pcpyld	$10, $10, $10
	addiu	$11, $0, 256
	pcpyh	$11, $11
	pcpyld	$11, $11, $11
	.p2align 3
1:	lq	$2, 0($8)
	lq	$3, 17408($8)
	psrlw	$4, $2, 24
	pref	0, 128($8)
	pextlw	$5, $4, $4
	pref	0, 17536($8)
	pcpyh	$5, $5
	pand	$5, $5, $10
	pextlb	$7, $0, $2
	pextuw	$6, $4, $4
	pmulth	$0, $7, $5
	pextlb	$13, $0, $3
	psubh	$4, $11, $5
	pmaddh	$0, $13, $4
	pcpyh	$6, $6
	pand	$6, $6, $10
	pextub	$12, $0, $2
	pmfhl.lh	$7
	pmulth	$0, $12, $6
	pextub	$14, $0, $3
	psubh	$2, $11, $6
	pmaddh	$0, $14, $2
	psrlh	$7, $7, 8
	pmfhl.lh	$12
	psrlh	$12, $12, 8
	ppacb	$3, $12, $7
	sq	$3, 17408($8)
	addiu	$8, $8, 16
	bne	$8, $9, 1b
	nop
	ADDR($4, gfx_mem, FRAME)
	j	app_hash
	ori	$5, $0, 16384
	.end	alpha_blend


# clut8: frame = palette[indexed], 16 pixels per iteration
# (mmi: the indices to palette addresses with MMI, each to a GPR by
# sll or dsra32), lw and sw per pixel, PREF of frame 4 lines ahead.
	.p2align 3
	.globl	clut8
	.ent	clut8
clut8:
	addiu	$sp, $sp, -128
	sq	$16, 0($sp)
	sq	$17, 16($sp)
	sq	$18, 32($sp)
	sq	$19, 48($sp)
	sq	$20, 64($sp)
	sq	$21, 80($sp)
	sq	$22, 96($sp)
	sq	$23, 112($sp)
	ADDR($8, gfx_mem, INDEXED)
	ADDR($9, gfx_mem, FRAME)
	ADDR($10, gfx_mem, PALETTE)
	addiu	$11, $8, 4096
	pextlw	$10, $10, $10
	pcpyld	$10, $10, $10
	.p2align 3
1:	lq	$12, 0($8)
	addiu	$8, $8, 16
	pref	0, 256($9)
	pextlb	$13, $0, $12
	pextlh	$14, $0, $13
	psllw	$14, $14, 2
	paddw	$14, $14, $10
	sll	$2, $14, 0
	pextuh	$13, $0, $13
	lw	$2, 0($2)
	pcpyud	$20, $14, $14
	dsra32	$3, $14, 0
	psllw	$13, $13, 2
	lw	$3, 0($3)
	sll	$4, $20, 0
	sw	$2, 0($9)
	paddw	$13, $13, $10
	lw	$4, 0($4)
	dsra32	$5, $20, 0
	sw	$3, 4($9)
	pextub	$12, $0, $12
	lw	$5, 0($5)
	sll	$6, $13, 0
	sw	$4, 8($9)
	pextlh	$15, $0, $12
	lw	$6, 0($6)
	pcpyud	$21, $13, $13
	sw	$5, 12($9)
	dsra32	$7, $13, 0
	sll	$24, $21, 0
	psllw	$15, $15, 2
	lw	$7, 0($7)
	paddw	$15, $15, $10
	sw	$6, 16($9)
	lw	$24, 0($24)
	dsra32	$25, $21, 0
	sw	$7, 20($9)
	sll	$16, $15, 0
	lw	$25, 0($25)
	pextuh	$12, $0, $12
	sw	$24, 24($9)
	pcpyud	$22, $15, $15
	lw	$16, 0($16)
	dsra32	$17, $15, 0
	psllw	$12, $12, 2
	sw	$25, 28($9)
	lw	$17, 0($17)
	sll	$18, $22, 0
	paddw	$12, $12, $10
	sw	$16, 32($9)
	lw	$18, 0($18)
	dsra32	$19, $22, 0
	sw	$17, 36($9)
	sll	$2, $12, 0
	lw	$19, 0($19)
	pcpyud	$23, $12, $12
	sw	$18, 40($9)
	dsra32	$3, $12, 0
	lw	$2, 0($2)
	sll	$4, $23, 0
	sw	$19, 44($9)
	dsra32	$5, $23, 0
	lw	$3, 0($3)
	sw	$2, 48($9)
	lw	$4, 0($4)
	sw	$3, 52($9)
	lw	$5, 0($5)
	sw	$4, 56($9)
	sw	$5, 60($9)
	bne	$8, $11, 1b
	addiu	$9, $9, 64
	lq	$16, 0($sp)
	lq	$17, 16($sp)
	lq	$18, 32($sp)
	lq	$19, 48($sp)
	lq	$20, 64($sp)
	lq	$21, 80($sp)
	lq	$22, 96($sp)
	lq	$23, 112($sp)
	addiu	$sp, $sp, 128
	ADDR($4, gfx_mem, FRAME)
	j	app_hash
	ori	$5, $0, 16384
	.end	clut8


# color_key: MMI per 4 pixels: pceqw with the key, the select by pxor, pand, pxor.
