	pceqw	$7, $5, $10
	pxor	$6, $5, $6
	lq	$15, 48($8)
	lq	$24, 17456($8)
	pxor	$2, $2, $3
	pand	$6, $6, $7
	lq	$16, 64($8)
	pceqw	$14, $12, $10
	lq	$17, 17472($8)
	pxor	$13, $12, $13
	sq	$2, 0($11)
	pxor	$5, $5, $6
	lq	$19, 80($8)
	pand	$13, $13, $14
	lq	$20, 17488($8)
	pceqw	$25, $15, $10
	sq	$5, 16($11)
	pxor	$24, $15, $24
	lq	$2, 96($8)
	pxor	$12, $12, $13
	lq	$3, 17504($8)
	pand	$24, $24, $25
	sq	$12, 32($11)
	pceqw	$18, $16, $10
	lq	$5, 112($8)
	pxor	$17, $16, $17
	lq	$6, 17520($8)
	pxor	$15, $15, $24
	pand	$17, $17, $18
	pceqw	$21, $19, $10
	sq	$15, 48($11)
	pxor	$20, $19, $20
	pxor	$16, $16, $17
	pand	$20, $20, $21
	sq	$16, 64($11)
	pceqw	$4, $2, $10
	pxor	$3, $2, $3
	pxor	$19, $19, $20
