# to_ct16: ppac5 (RGBA8888 to 1555 per word, the C formula) and ppach
# per 8 pixels; 4 x 8 pixels per iteration, PREF 4 lines ahead.
	.p2align 3
	.globl	to_ct16
	.ent	to_ct16
to_ct16:
	ADDR($8, gfx_mem, SPRITE)
	ADDR($9, gfx_mem, FRAME16)
	addiu	$10, $8, 16384
	.p2align 3
1:	lq	$2, 0($8)
	lq	$3, 16($8)
	lq	$4, 32($8)
	ppac5	$2, $2
	lq	$5, 48($8)
	ppac5	$3, $3
	lq	$6, 64($8)
	ppach	$2, $3, $2
	lq	$7, 80($8)
	ppac5	$4, $4
	ppac5	$5, $5
	lq	$12, 96($8)
	lq	$13, 112($8)
	ppach	$4, $5, $4
	sq	$2, 0($9)
	ppac5	$6, $6
	ppac5	$7, $7
	sq	$4, 16($9)
	ppach	$6, $7, $6
	pref	0, 256($8)
	ppac5	$12, $12
	sq	$6, 32($9)
	ppac5	$13, $13
	pref	0, 320($8)
	ppach	$12, $13, $12
	sq	$12, 48($9)
	addiu	$8, $8, 128
	bne	$8, $10, 1b
	addiu	$9, $9, 64
	ADDR($4, gfx_mem, FRAME16)
	j	app_hash
	ori	$5, $0, 8192
	.end	to_ct16


